import{_ as e,o as a,c as l,a5 as d}from"./chunks/framework.a5no_H3L.js";const g=JSON.parse('{"title":"Redis 配置参数参考","description":"本页以 Redis 7.4.11 默认配置为基准。“调优方向”不是通用推荐值；实际配置必须结合数据用途、RPO、主机资源和压测结果。修改前使用 CONFIG GET 确认当前实例值，并记录变更原因。","frontmatter":{},"headers":[],"relativePath":"redis/reference/parameters.md","filePath":"redis/reference/parameters.md"}'),r={name:"redis/reference/parameters.md"};function s(i,t,n,f,c,y){return a(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="redis-配置参数参考" tabindex="-1" data-src-line="1" data-src-file="redis/reference/parameters.md">Redis 配置参数参考 <a class="header-anchor" href="#redis-配置参数参考" aria-label="Permalink to &quot;Redis 配置参数参考&quot;">​</a></h1><p data-src-line="3" data-src-file="redis/reference/parameters.md">本页以 Redis 7.4.11 默认配置为基准。“调优方向”不是通用推荐值；实际配置必须结合数据用途、RPO、主机资源和压测结果。修改前使用 <code>CONFIG GET &lt;参数&gt;</code> 确认当前实例值，并记录变更原因。</p><h2 id="内存管理" tabindex="-1" data-src-line="5" data-src-file="redis/reference/parameters.md">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><table tabindex="0"><thead data-src-line="7" data-src-file="redis/reference/parameters.md"><tr data-src-line="7" data-src-file="redis/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">调优方向</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="9" data-src-file="redis/reference/parameters.md"><tr data-src-line="9" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>maxmemory</code></td><td style="text-align:left;">0（不限制）</td><td style="text-align:left;">根据主机、容器、fork 和增长速度计算</td><td style="text-align:left;">最大内存限制</td></tr><tr data-src-line="10" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>maxmemory-policy</code></td><td style="text-align:left;">noeviction</td><td style="text-align:left;">缓存可选 LRU/LFU；主数据通常保持 noeviction</td><td style="text-align:left;">淘汰策略</td></tr><tr data-src-line="11" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>maxmemory-samples</code></td><td style="text-align:left;">5</td><td style="text-align:left;">压测后提高采样精度</td><td style="text-align:left;">LRU/TTL 采样精度</td></tr><tr data-src-line="12" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>lazyfree-lazy-eviction</code></td><td style="text-align:left;">no</td><td style="text-align:left;">yes</td><td style="text-align:left;">异步淘汰，避免阻塞</td></tr><tr data-src-line="13" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>lazyfree-lazy-expire</code></td><td style="text-align:left;">no</td><td style="text-align:left;">yes</td><td style="text-align:left;">异步过期删除</td></tr></tbody></table><h2 id="淘汰策略说明" tabindex="-1" data-src-line="15" data-src-file="redis/reference/parameters.md">淘汰策略说明 <a class="header-anchor" href="#淘汰策略说明" aria-label="Permalink to &quot;淘汰策略说明&quot;">​</a></h2><table tabindex="0"><thead data-src-line="17" data-src-file="redis/reference/parameters.md"><tr data-src-line="17" data-src-file="redis/reference/parameters.md"><th style="text-align:left;">策略</th><th style="text-align:left;">范围</th><th style="text-align:left;">算法</th><th style="text-align:left;">适用场景</th></tr></thead><tbody data-src-line="19" data-src-file="redis/reference/parameters.md"><tr data-src-line="19" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>noeviction</code></td><td style="text-align:left;">-</td><td style="text-align:left;">不淘汰，写入报错</td><td style="text-align:left;">不能主动丢弃数据的实例</td></tr><tr data-src-line="20" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>allkeys-lru</code></td><td style="text-align:left;">所有 key</td><td style="text-align:left;">LRU</td><td style="text-align:left;">通用缓存</td></tr><tr data-src-line="21" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>allkeys-lfu</code></td><td style="text-align:left;">所有 key</td><td style="text-align:left;">LFU</td><td style="text-align:left;">热点数据明显</td></tr><tr data-src-line="22" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>volatile-lru</code></td><td style="text-align:left;">有 TTL 的 key</td><td style="text-align:left;">LRU</td><td style="text-align:left;">缓存+持久混合</td></tr><tr data-src-line="23" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>volatile-lfu</code></td><td style="text-align:left;">有 TTL 的 key</td><td style="text-align:left;">LFU</td><td style="text-align:left;">缓存+持久混合</td></tr><tr data-src-line="24" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>volatile-ttl</code></td><td style="text-align:left;">有 TTL 的 key</td><td style="text-align:left;">TTL 最短优先</td><td style="text-align:left;">过期数据优先淘汰</td></tr><tr data-src-line="25" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>volatile-random</code></td><td style="text-align:left;">有 TTL 的 key</td><td style="text-align:left;">随机</td><td style="text-align:left;">无明确热点</td></tr><tr data-src-line="26" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>allkeys-random</code></td><td style="text-align:left;">所有 key</td><td style="text-align:left;">随机</td><td style="text-align:left;">无明确热点</td></tr></tbody></table><h2 id="持久化" tabindex="-1" data-src-line="28" data-src-file="redis/reference/parameters.md">持久化 <a class="header-anchor" href="#持久化" aria-label="Permalink to &quot;持久化&quot;">​</a></h2><table tabindex="0"><thead data-src-line="30" data-src-file="redis/reference/parameters.md"><tr data-src-line="30" data-src-file="redis/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">调优方向</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="32" data-src-file="redis/reference/parameters.md"><tr data-src-line="32" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>save</code></td><td style="text-align:left;">3600 1 300 100 60 10000</td><td style="text-align:left;">按 RPO、fork 成本和恢复时间调整</td><td style="text-align:left;">RDB 触发条件</td></tr><tr data-src-line="33" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>appendonly</code></td><td style="text-align:left;">no</td><td style="text-align:left;">需要命令级恢复点时开启</td><td style="text-align:left;">开启 AOF</td></tr><tr data-src-line="34" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>appendfsync</code></td><td style="text-align:left;">everysec</td><td style="text-align:left;">通常为 everysec，并结合 RPO 压测</td><td style="text-align:left;">AOF 刷盘策略</td></tr><tr data-src-line="35" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>auto-aof-rewrite-percentage</code></td><td style="text-align:left;">100</td><td style="text-align:left;">100</td><td style="text-align:left;">AOF 重写触发比例</td></tr><tr data-src-line="36" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>auto-aof-rewrite-min-size</code></td><td style="text-align:left;">64mb</td><td style="text-align:left;">根据文件增长和恢复时间调整</td><td style="text-align:left;">AOF 重写最小大小</td></tr></tbody></table><h2 id="连接与超时" tabindex="-1" data-src-line="38" data-src-file="redis/reference/parameters.md">连接与超时 <a class="header-anchor" href="#连接与超时" aria-label="Permalink to &quot;连接与超时&quot;">​</a></h2><table tabindex="0"><thead data-src-line="40" data-src-file="redis/reference/parameters.md"><tr data-src-line="40" data-src-file="redis/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">调优方向</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="42" data-src-file="redis/reference/parameters.md"><tr data-src-line="42" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>bind</code></td><td style="text-align:left;">127.0.0.1 与 ::1</td><td style="text-align:left;">私网地址或回环地址</td><td style="text-align:left;">监听地址；容器网络需单独判断</td></tr><tr data-src-line="43" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>port</code></td><td style="text-align:left;">6379</td><td style="text-align:left;">6379</td><td style="text-align:left;">监听端口</td></tr><tr data-src-line="44" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>timeout</code></td><td style="text-align:left;">0（不超时）</td><td style="text-align:left;">根据客户端连接模式决定</td><td style="text-align:left;">主动断开空闲客户端的秒数</td></tr><tr data-src-line="45" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>tcp-keepalive</code></td><td style="text-align:left;">300</td><td style="text-align:left;">结合网络和中间设备超时验证</td><td style="text-align:left;">TCP 心跳间隔（秒）</td></tr><tr data-src-line="46" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>maxclients</code></td><td style="text-align:left;">10000</td><td style="text-align:left;">根据连接池上限和文件描述符预算调整</td><td style="text-align:left;">最大客户端连接数</td></tr></tbody></table><h2 id="性能" tabindex="-1" data-src-line="48" data-src-file="redis/reference/parameters.md">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to &quot;性能&quot;">​</a></h2><table tabindex="0"><thead data-src-line="50" data-src-file="redis/reference/parameters.md"><tr data-src-line="50" data-src-file="redis/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">调优方向</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="52" data-src-file="redis/reference/parameters.md"><tr data-src-line="52" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>hz</code></td><td style="text-align:left;">10</td><td style="text-align:left;">默认保持 10，有明确需求时再压测调整</td><td style="text-align:left;">后台任务频率</td></tr><tr data-src-line="53" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>io-threads</code></td><td style="text-align:left;">1</td><td style="text-align:left;">压测决定，通常不超过 CPU 核数</td><td style="text-align:left;">IO 线程数（6.0+）</td></tr><tr data-src-line="54" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>io-threads-do-reads</code></td><td style="text-align:left;">no</td><td style="text-align:left;">默认保持 no，除非压测证明有收益</td><td style="text-align:left;">读操作也使用 IO 线程（6.0+）</td></tr><tr data-src-line="55" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>lazyfree-lazy-server-del</code></td><td style="text-align:left;">no</td><td style="text-align:left;">大 Key 删除场景压测后开启</td><td style="text-align:left;">让服务端 DEL 走异步回收</td></tr></tbody></table><h2 id="复制与故障转移" tabindex="-1" data-src-line="57" data-src-file="redis/reference/parameters.md">复制与故障转移 <a class="header-anchor" href="#复制与故障转移" aria-label="Permalink to &quot;复制与故障转移&quot;">​</a></h2><table tabindex="0"><thead data-src-line="59" data-src-file="redis/reference/parameters.md"><tr data-src-line="59" data-src-file="redis/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">调优方向</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="61" data-src-file="redis/reference/parameters.md"><tr data-src-line="61" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>repl-backlog-size</code></td><td style="text-align:left;">1mb</td><td style="text-align:left;">按断线容忍时长和峰值复制写入速率计算</td><td style="text-align:left;">支持 partial resync 的环形缓冲区</td></tr><tr data-src-line="62" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>repl-backlog-ttl</code></td><td style="text-align:left;">3600</td><td style="text-align:left;">结合副本重启和重连窗口调整</td><td style="text-align:left;">最后一个副本断开后保留 backlog 的秒数</td></tr><tr data-src-line="63" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>replica-serve-stale-data</code></td><td style="text-align:left;">yes</td><td style="text-align:left;">根据应用能否接受旧数据决定</td><td style="text-align:left;">副本无法同步时是否返回旧数据</td></tr><tr data-src-line="64" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>replica-read-only</code></td><td style="text-align:left;">yes</td><td style="text-align:left;">通常保持 yes</td><td style="text-align:left;">副本只读保护</td></tr><tr data-src-line="65" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>min-replicas-to-write</code></td><td style="text-align:left;">0</td><td style="text-align:left;">根据可用副本和误判成本设置</td><td style="text-align:left;">满足副本数量保护时才允许写入</td></tr><tr data-src-line="66" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>min-replicas-max-lag</code></td><td style="text-align:left;">10</td><td style="text-align:left;">结合复制基线和 RPO 设置</td><td style="text-align:left;">副本允许的最大延迟秒数</td></tr></tbody></table><h2 id="网络与安全" tabindex="-1" data-src-line="68" data-src-file="redis/reference/parameters.md">网络与安全 <a class="header-anchor" href="#网络与安全" aria-label="Permalink to &quot;网络与安全&quot;">​</a></h2><table tabindex="0"><thead data-src-line="70" data-src-file="redis/reference/parameters.md"><tr data-src-line="70" data-src-file="redis/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">调优方向</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="72" data-src-file="redis/reference/parameters.md"><tr data-src-line="72" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>protected-mode</code></td><td style="text-align:left;">yes</td><td style="text-align:left;">非受信网络中保持 yes</td><td style="text-align:left;">无绑定地址且无密码时阻止外部访问</td></tr><tr data-src-line="73" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>requirepass</code></td><td style="text-align:left;">空</td><td style="text-align:left;">新部署优先使用 ACL</td><td style="text-align:left;">传统整体密码</td></tr><tr data-src-line="74" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>aclfile</code></td><td style="text-align:left;">空</td><td style="text-align:left;">多应用部署使用 ACL 文件或运行时 ACL</td><td style="text-align:left;">从文件加载 ACL 用户</td></tr><tr data-src-line="75" data-src-file="redis/reference/parameters.md"><td style="text-align:left;"><code>tls-port</code></td><td style="text-align:left;">0</td><td style="text-align:left;">跨不可信网络时启用并验证证书</td><td style="text-align:left;">TLS 监听端口</td></tr></tbody></table>',16)])])}const o=e(r,[["render",s]]);export{g as __pageData,o as default};
